import 'package:flutter/material.dart';import 'package:supabase_flutter/supabase_flutter.dart';import '../theme/app_theme.dart';
class WithdrawScreen extends StatefulWidget{const WithdrawScreen({super.key});@override State<WithdrawScreen>createState()=>_WithdrawState();}
class _WithdrawState extends State<WithdrawScreen>{String method='bKash';final amount=TextEditingController(),destination=TextEditingController();bool busy=false;String? msg;Future<void>submit()async{setState(()=>busy=true);try{final a=double.tryParse(amount.text.trim());if(a==null||a<=0)throw Exception('Enter a valid amount');final r=await Supabase.instance.client.functions.invoke('request-withdrawal',body:{'amount':a,'paymentMethod':method,'paymentDestination':destination.text.trim()});if(r.data is Map&&r.data['error']!=null)throw Exception(r.data['error']);setState(()=>msg='Withdrawal request submitted');}catch(e){setState(()=>msg=e.toString());}finally{if(mounted)setState(()=>busy=false);}}@override void dispose(){amount.dispose();destination.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Withdraw')),body:ListView(padding:const EdgeInsets.all(18),children:[const Text('Withdrawal Method'),const SizedBox(height:8),DropdownButtonFormField<String>(value:method,items:const['bKash','Nagad','Bank Transfer'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>method=v!)),const SizedBox(height:14),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount',prefixText:'৳ ')),const SizedBox(height:14),TextField(controller:destination,decoration:const InputDecoration(labelText:'Payment destination')),if(msg!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(msg!,style:TextStyle(color:msg!.contains('submitted')?AppTheme.green:AppTheme.red))),const SizedBox(height:18),ElevatedButton(onPressed:busy?null:submit,style:ElevatedButton.styleFrom(backgroundColor:AppTheme.green,foregroundColor:Colors.black),child:Text(busy?'Submitting...':'Request Withdrawal')),const SizedBox(height:8),const Center(child:Text('Withdrawal is available only when unlocked by Admin.',style:TextStyle(color:AppTheme.muted))) ]));}
}
